            current, index = work[-1]
            if index >= len(current):
                work.pop()
                continue
            op = current[index]
            work[-1] = (current, index + 1)
            if op[0] == "num":
                push(op[1])
            elif op[0] == "builtin":
                op[1]()
            elif op[1] is None:
                raise ValueError("undefined operation")
            else:
                work.append((op[1], 0))

    for line in input_data:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0] == ":":
            name = tokens[1].lower()
            if _is_number(name):
                raise ValueError("illegal operation")
            body = []
            for token in tokens[2:]:
                if token == ";":
                    break
                if _is_number(token):
                    body.append(("num", int(token)))
                else:
                    word_name = token.lower()
                    if word_name in words:
                        body.append(("word", words[word_name]))
                    elif word_name in builtins:
                        body.append(("builtin", builtins[word_name]))
                    else:
                        body.append(("word", None))
            words[name] = body
        else:
            for token in tokens:
                if _is_number(token):
                    push(int(token))
                elif token.lower() in words:
                    execute(words[token.lower()])
                elif token.lower() in builtins:
                    builtins[token.lower()]()
                else:
                    raise ValueError("undefined operation")
    return stack
